package cn.qqworkbench.assistant;

import android.app.AlertDialog;
import android.content.Intent;
import android.widget.*;
import org.json.*;

final class VoiceReferences {
    static final String[] LABELS={"自然","开心","温柔","害羞（参考表达）","难过","认真"};
    static void importedPack(MainActivity a,android.net.Uri uri){if(uri==null)return;VoicePreview.cancel(a);int slot=a.pendingVoiceSlot;a.io.submit(()->{java.io.File file=new java.io.File(a.getCacheDir(),"voice-pack-"+java.util.UUID.randomUUID()+".zip");try{try(java.io.InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new java.io.IOException("参考包无法读取");java.nio.file.Files.write(file.toPath(),LocalVoice.read(in,13*1024*1024));}JSONObject imported=LocalVoiceClient.call(a,"import-reference-pack",new JSONObject().put("slot",slot).put("file",file.getName()));a.runOnUiThread(()->{a.toast("参考库已保存，原声音已备份；选择参考克隆并保存即可启用");applyImported(a,slot,imported.optString("presetName","我的导入预设"),"neutral",imported.optString("presetId"));});}catch(Exception e){a.runOnUiThread(()->a.toast("导入未完成："+e.getMessage()));}finally{file.delete();}});}
    static void choosePack(MainActivity a,int slot){a.pendingVoiceSlot=slot;try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("*/*").addCategory(Intent.CATEGORY_OPENABLE),77);}catch(Exception e){a.toast("文件选择器不可用");}}
    static void chooseSingle(MainActivity a,int slot){LinearLayout fields=new LinearLayout(a);fields.setOrientation(1);EditText name=new EditText(a);name.setHint("音色名称（可选）");name.setSingleLine(true);fields.addView(name);EditText text=new EditText(a);fields.addView(text);text.setHint("填写录音里准确说出的文字");text.setMinLines(2);new AlertDialog.Builder(a).setTitle("导入1–10秒清晰人声").setMessage("单段参考会建立独立音色，避免与之前人物的语气或短回应混用。").setView(fields).setPositiveButton("选择音频",(d,n)->{String value=text.getText().toString().trim();if(value.isEmpty()||value.length()>200){a.toast("请填写1到200字准确转写");return;}a.pendingVoiceSlot=slot;a.pendingVoiceText=value;a.pendingVoiceName=name.getText().toString().trim();try{a.startActivityForResult(new Intent(Intent.ACTION_OPEN_DOCUMENT).setType("audio/*").addCategory(Intent.CATEGORY_OPENABLE),79);}catch(Exception e){a.pendingVoiceText="";a.toast("文件选择器不可用");}}).setNegativeButton("取消",null).show();}
    static void applyImported(MainActivity a,int slot,String name,String mood,String id){if(a.destroyed)return;if(a.activeVoicePanel!=null&&a.activeVoicePanel.slot==slot){a.activeVoicePanel.imported(name,mood,id);return;}try{if(slot==0)a.patch(new JSONObject().put("speechProvider","zipvoice").put("voiceEnabled",true).put("voicePresetName",name).put("voicePresetId",id));VoicePreview.imported(a,slot,mood);}catch(Exception e){a.toast("参考已导入，请在语音页启用");}}
    static void importedSingle(MainActivity a,android.net.Uri uri){int slot=a.pendingVoiceSlot;String text=a.pendingVoiceText,name=a.pendingVoiceName;a.pendingVoiceText="";a.pendingVoiceName="";if(uri==null||text.isEmpty())return;VoicePreview.cancel(a);a.toast("正在校验并建立独立音色…");a.io.submit(()->{java.io.File file=new java.io.File(a.getCacheDir(),"voice-single-"+java.util.UUID.randomUUID()+".bin");try{try(java.io.InputStream in=a.getContentResolver().openInputStream(uri)){if(in==null)throw new java.io.IOException("音频无法读取");java.nio.file.Files.write(file.toPath(),LocalVoice.read(in,12*1024*1024));}JSONObject imported=LocalVoiceClient.call(a,"import-single-preset",new JSONObject().put("slot",slot).put("file",file.getName()).put("text",text).put("name",name.isEmpty()?"我的音色 "+new java.text.SimpleDateFormat("MMdd-HHmmss",java.util.Locale.ROOT).format(new java.util.Date()):name));a.runOnUiThread(()->applyImported(a,slot,imported.optString("presetName","我的导入音色"),"neutral",imported.optString("presetId")));}catch(Exception e){a.runOnUiThread(()->a.toast("导入未完成："+e.getMessage()));}finally{file.delete();}});}
    static void imported(MainActivity a,android.net.Uri uri){int slot=a.pendingVoiceSlot;String mood=a.pendingVoiceMood,text=a.pendingVoiceText;a.pendingVoiceText="";if(uri==null||text.isEmpty())return;VoicePreview.cancel(a);a.toast("正在读取本机录音…");a.io.submit(()->{try{LocalVoice.get(a).importReference(slot,mood,uri,text);a.runOnUiThread(()->{a.toast("参考已保存，未上传录音");VoicePreview.imported(a,slot,mood);});}catch(Exception e){a.runOnUiThread(()->a.toast("导入未完成："+e.getMessage()));}});}
}
